import java.util.*;
import java.util.stream.*;

public class Batch {
    static final int BATCH_SIZE = 100;

    static void sendInBatches(List<String> hires) {
        for (int i = 0; i < hires.size(); i += BATCH_SIZE) {
            List<String> batch = hires.subList(i, i + BATCH_SIZE);
            System.out.println("Sending " + batch.size() + " hires to CPI");
        }
    }

    public static void main(String[] args) {
        List<String> hires = IntStream.rangeClosed(1, 250)
            .mapToObj(n -> "A-" + n).toList();
        sendInBatches(hires);
    }
}

