public class Split {
    // line format: applicationId|candidateId|offerId|startDate
    static String offerId(String line) {
        String[] parts = line.split("\\|");
        return parts[2].isEmpty() ? null : parts[2];
    }

    public static void main(String[] args) {
        System.out.println(offerId("A-100|C-1042|O-7|2026-11-02"));
        System.out.println(offerId("A-101|C-1043||"));
    }
}

