public class Route {
    record RecruitingEvent(String eventId, String type, String applicationId) {}

    static String route(RecruitingEvent event) {
        switch (event.type()) {
            case "HIRED" -> { return "store and forward to CPI"; }
            case "OFFER_ACCEPTED" -> { return "store only"; }
            default -> { return "ignore"; }
        }
    }

    public static void main(String[] args) {
        System.out.println(route(new RecruitingEvent("evt-1", "HIRED", "A-100")));
        // the JSON from the test system has no "type" field
        System.out.println(route(new RecruitingEvent("evt-2", null, "A-101")));
    }
}

