static final ThreadLocal<String> CORRELATION_ID = new ThreadLocal<>();

// called by the controller on the request thread
void onHire(String eventId, String json) {
    CORRELATION_ID.set(eventId);
    pool.submit(() -> forward(json));
}

void forward(String json) {
    HttpRequest.Builder b = HttpRequest.newBuilder(cpiUri)
        .timeout(Duration.ofSeconds(10))
        .POST(HttpRequest.BodyPublishers.ofString(json));
    String id = CORRELATION_ID.get();
    if (id != null) {
        b.header("X-Correlation-Id", id);
    }
    try {
        client.send(b.build(), HttpResponse.BodyHandlers.discarding());
    } catch (Exception e) {
        log.warn("Forward failed", e);
    }
}

