    HttpRequest request = HttpRequest.newBuilder(cpiUri)
        .[[1]](Duration.ofSeconds(10))
        .header("X-Correlation-Id", [[2]])
        .header("Content-Type", "application/json")
        .POST(HttpRequest.BodyPublishers.ofString(json))
        .build();
    try {
        HttpResponse<Void> response =
            client.send(request, HttpResponse.BodyHandlers.discarding());
        if (response.statusCode() [[3]]) {
            markForwarded(eventId);
        } else {
            log.warn("CPI answered {} for {}", response.statusCode(), eventId);
        }
    } catch (IOException e) {             // includes HttpTimeoutException
        log.warn("Forward failed for {}, it stays RECEIVED", eventId, e);
    } catch (InterruptedException e) {
        Thread.currentThread().interrupt();
    }
